/* Visible final-ticket requests and an explicitly simulated checkout. No processor calls. */
function demoPaymentLink(b){return '/app/?role=customer&demoCheckout='+encodeURIComponent(b.id);}
function postFinalPaymentRequest(b){const thread=threadFor(b.client,b.barber),id=`payment-request-${b.id}-${b.ticket.revision}`;if(!thread.messages.some(m=>m.id===id))thread.messages.push({id,role:'Barber Pro',name:barbers.find(x=>x.id===b.barber)?.name||'Your barber',body:'Your final ticket is ready. Review your services, choose a tip and continue to payment.',at:Date.now(),readBy:['barber:'+b.barber],delivered:true,paymentRequest:{bookingId:b.id,revision:b.ticket.revision}});b.paymentRequest={revision:b.ticket.revision,at:Date.now()};}
function paymentRequestCard(b){return `<section class="panel final-payment-request"><span class="badge">${icon('card')} Final ticket ready</span><h2>${esc(barbers.find(x=>x.id===b.barber)?.name||'Your barber')} sent your checkout link.</h2><p>Review your final services, choose an optional tip, then continue to payment.</p><div class="line-item"><span>Services</span><strong>${cents(b.ticket.snapshot?.subtotalCents??b.ticket.approval?.subtotalCents??b.estimateCents)}</strong></div><a class="btn full" href="${demoPaymentLink(b)}" data-payment-preview="open" data-id="${esc(b.id)}">${icon('card')} ${b.ticket.approval?'Continue to payment':'Review ticket & pay'} ${icon('arrow')}</a><small>Interactive preview · No real charge</small></section>`;}
function openPaymentRequest(id){const b=bookings.find(x=>x.id===id&&x.client==='John B.');if(!b){toast('This request is not available in this browser.');return;}state.visitId=b.id;if(b.settlement?.status==='paid'){go('cReceipt');return;}if(b.ticket?.status==='awaiting_approval')go('cApproval');else if(b.ticket?.approval)go('demoPayment');else{toast('The ticket was changed. Wait for your barber to resend it.');go('bookings');}}
function demoPaymentPage(){const b=bookings.find(x=>x.id===state.visitId&&x.client==='John B.');if(!b?.ticket?.approval)return approvalPage();if(b.settlement?.status==='paid')return receiptPage();const a=b.ticket.approval;return `<div class="narrow">${head('Finish your visit.','Your services and tip, ready to settle.')}<section class="panel final-payment-request">${visitSummary(b)}${lineSummary(a.lines)}<div class="line-item"><span>Services</span><strong>${cents(a.subtotalCents)}</strong></div><div class="line-item"><span>Tip</span><strong>${cents(a.tipCents)}</strong></div><div class="line-item total"><strong>Total</strong><strong>${cents(a.totalCents)}</strong></div><p class="notice">Payment simulation. No card details are collected and no money will be charged.</p><button class="btn full" data-payment-preview="pay" data-id="${esc(b.id)}">Complete demo payment · ${cents(a.totalCents)}</button><p class="payment-preview-error" role="alert"></p></section></div>`;}
const approvalBeforePaymentPreview=approvalPage;approvalPage=function(){return approvalBeforePaymentPreview().replace('Approve final ticket','Continue to payment');};
const extraBeforePaymentPreview=renderExtraView;renderExtraView=function(view){if(view==='demoPayment')return state.role==='Customer'?demoPaymentPage():head('Customer checkout.','Open the customer view to continue.');return extraBeforePaymentPreview(view);};
const goBeforePaymentPreview=go;go=function(view){const b=bookings.find(x=>x.id===state.visitId);if(view==='cReceipt'&&state.role==='Customer'&&b?.paymentRequest&&b.ticket?.approval&&b.settlement?.status!=='paid')view='demoPayment';return goBeforePaymentPreview(view);};
const renderBeforePaymentPreview=render;render=function(){renderBeforePaymentPreview();if(state.role==='Customer'){const pending=bookings.filter(b=>b.client==='John B.'&&b.status!=='cancelled'&&(b.ticket?.status==='awaiting_approval'||b.ticket?.approval&&b.settlement?.status!=='paid')).sort((a,b)=>(b.ticket?.sentAt||0)-(a.ticket?.sentAt||0));if(['home','bookings'].includes(state.view)&&pending.length)document.querySelector('#main .page-head')?.insertAdjacentHTML('afterend',paymentRequestCard(pending[0]));if(state.view==='cReceipt'&&bookings.find(b=>b.id===state.visitId)?.settlement?.source==='simulation')document.querySelector('#main .page-head')?.insertAdjacentHTML('afterend','<p class="notice">Simulated payment complete · No money was charged</p>');if(state.view==='messages'){const thread=extras.conversations.find(t=>t.id===state.threadId);for(const message of thread?.messages||[]){const id=message.paymentRequest?.bookingId,b=bookings.find(b=>b.id===id);if(!b||b.status==='cancelled')continue;const bubble=[...document.querySelectorAll('.message-bubble')].find(el=>el.textContent.includes(message.body)&&!el.querySelector('[data-payment-preview]'));bubble?.insertAdjacentHTML('beforeend',`<a class="btn full payment-chat-link" href="${demoPaymentLink(b)}" data-payment-preview="open" data-id="${esc(b.id)}">${b.settlement?.status==='paid'?'View receipt':'Review ticket & pay'} ${icon('arrow')}</a>`);}}}
 if(isStaff()&&['pTicket','pFinalize','pAppointment','staffReceipt'].includes(state.view)){const b=visitFor();if(b?.ticket?.status==='awaiting_approval')document.querySelector('#main')?.insertAdjacentHTML('afterbegin',`<section class="panel final-payment-request"><h2>Checkout request sent.</h2><p>Posted in ${esc(b.client)}’s conversation.</p>${b.client==='John B.'?`<a class="btn secondary" href="${demoPaymentLink(b)}" target="_blank" rel="noopener">Open customer checkout ${icon('arrow')}</a>`:''}<small>Preview link uses records saved in this browser.</small></section>`);if(b?.settlement?.source==='simulation')document.querySelector('#main .page-head')?.insertAdjacentHTML('afterend','<p class="notice">Simulated payment recorded · No real charge</p>');}
};
document.addEventListener('click',e=>{const link=e.target.closest('[data-payment-preview]');if(!link)return;e.preventDefault();if(state.role!=='Customer')return;const b=bookings.find(b=>b.id===link.dataset.id&&b.client==='John B.');if(!b)return;if(link.dataset.paymentPreview==='open'){openPaymentRequest(b.id);return;}if(link.dataset.paymentPreview==='pay'&&b.ticket?.approval&&b.settlement?.status!=='paid'){b.settlement={status:'paid',method:'card',source:'simulation',amountCents:b.ticket.approval.totalCents,at:Date.now()};save();go('cReceipt');toast('Demo payment complete. No money was charged.');}});
function seedPaymentPreview(){if(extras.paymentPreviewDay===today)return;const service=servicesFor('alex').find(s=>s.id==='cut');if(!service)return;const existing=bookings.find(b=>b.client==='John B.'&&b.ticket?.status==='awaiting_approval');if(existing){postFinalPaymentRequest(existing);extras.paymentPreviewDay=today;save();return;}const time=times.find(t=>minutes(t)>=540&&minutes(t)+service.min<=1080&&!bookings.some(b=>b.barber==='alex'&&b.date===today&&b.status!=='cancelled'&&overlaps(t,service.min,b.time,bookingDuration(b)))&&!extras.blocks.some(b=>b.barber==='alex'&&b.date===today&&clockMinutes(b.start)<minutes(t)+service.min&&clockMinutes(b.end)>minutes(t)));if(!time)return;const id=`payment-preview-${today}`,b={id,client:'John B.',barber:'alex',service:service.id,services:[service.id],bookedServices:[{...service}],durationMin:service.min,estimateCents:Math.round(service.price*100),date:today,time,location:'scottsdale',status:'awaiting_approval',policy:structuredClone(extras.bookingPolicy),presentationExample:true};b.ticket=HFTickets.create(id,service);HFTickets.finalize(b.ticket);HFTickets.send(b.ticket);bookings.push(b);postFinalPaymentRequest(b);extras.paymentPreviewDay=today;save();}
seedPaymentPreview();
const checkoutQuery=new URL(location.href).searchParams.get('demoCheckout');if(checkoutQuery&&state.role==='Customer'){const id=checkoutQuery==='latest'?bookings.filter(b=>b.client==='John B.'&&b.paymentRequest).at(-1)?.id:checkoutQuery;if(id)openPaymentRequest(id);else render();}else render();
